// 1. Primitive Atom — 직접 값 저장
const countAtom = atom(0)

// 2. Read-only Derived — 다른 atom으로부터 계산
const doubleAtom = atom((get) => get(countAtom) * 2)

// 3. Writable Derived — 읽기 + 쓰기
const upperNameAtom = atom(
  (get) => get(nameAtom).toUpperCase(),          // read
  (get, set, newName) => set(nameAtom, newName)  // write
)

// 4. Write-only — 액션 용도
const resetAtom = atom(
  null,
  (get, set) => set(countAtom, 0)
)

